import{_ as t,a,b as i}from"./chunks/fixpipe_buffer.DVuNbORL.js";import{_ as r,o as _,a as p,b as o}from"./app.ejsEy6QV.js";const I=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"矩阵计算搬运","link":"/api/SIMD-API/c_api/cube_datamove/cube_datamove"},{"text":"矩阵搬出总体说明","link":"/api/SIMD-API/c_api/cube_datamove/cube_compute_store_overall_description"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/cube_datamove/cube_compute_store_overall_description.md","filePath":"api/SIMD-API/c_api/cube_datamove/cube_compute_store_overall_description.md","lastUpdated":1789544578000}'),s={name:"api/SIMD-API/c_api/cube_datamove/cube_compute_store_overall_description.md"};function n(c,e,d,l,m,u){return _(),p("div",null,[...e[0]||(e[0]=[o('<div><article class="markdown-body"><h1>矩阵搬出总体说明</h1><p>矩阵计算的搬出是Ascend C编程框架中用于数据搬运的一类核心接口，主要实现从L0C Buffer到Global Memory和L1 Buffer的数据传输。该接口系列提供了多种数据搬运模式，能够满足矩阵计算中的数据搬运需求，通常在asc_mmad接口后配合使用。</p><p>矩阵计算的搬出接口支持多种随路搬运场景，包括<strong>随路量化、随路ReLU、随路格式转换（Nz2ND、Nz2DN）、随路通道拆分（Channel Split）、随路通道合并（Channel Merge）</strong>。通过配置接口参数与辅助寄存器，开发者可以精确控制数据的搬运路径、起始位置、搬运长度、随路搬运能力等关键信息，充分利用硬件的数据搬运能力，最大化算子的整体执行性能。</p><div data-filter="950,A3,910b"><p>矩阵计算的搬出整体流程如下图所示：</p></div><div data-filter="A3,910b"><p><strong>图1</strong> 矩阵计算的搬出整体流程图（<a href="../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>）</p><p><img src="'+t+'" alt></p></div><div data-filter="950"><p><strong>图2</strong> 矩阵计算的搬出整体流程图（<a href="../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>）</p><p><img src="'+a+'" alt></p></div><p>其中，Fixpipe Buffer不同的量化模式对应的内存排布如下：</p><p><strong>图3</strong> Fixpipe Buffer内存排布图</p><p><img src="'+i+'" alt></p></article></div>',1)])])}const b=r(s,[["render",n]]);export{I as __pageData,b as default};
